import {sensors,defaults,apertures,shutters,isos,focalStops,actors,actorDistance,moveActor,metrics,effective,changeSensor,clamp,nearest,shutterText,distanceText,encodeState,decodeState} from './physics.mjs';
import {drawPhoto,drawSensors} from './renderer.mjs';
import {drawCutaway,drawRoom} from './camera-view.mjs';
import {comparisonRows} from './state-info.mjs';
import {lessons,learnPage,aboutPage,atlasPage} from './content.mjs';
const $=id=>document.getElementById(id);
let state=location.hash.startsWith('#s=')?decodeState(location.hash):{...defaults};
let saved=null,photoHit=null,spaceHit=null,cameraHit=null,drag=null,activeLesson=null,needsRender=true,activeControl='aperture',motionTarget='ballSpeed',roomSelected='person',settingsTab='base',simTime=0,lastTime=0,lastTick=performance.now();
const canvas=$('canvas'),cameraCanvas=$('camera-canvas'),spaceCanvas=$('space-canvas');
const help={
 focal:['Brennweite','Stufen und Marken zeigen klassische reale Brennweiten. Bei festem Standpunkt ändert Zoom den Bildausschnitt, nicht die Perspektive.'],
 aperture:['Blende','Kleine ƒ-Zahl: große Öffnung, mehr Licht, weniger Schärfentiefe. „Auto“ lässt die Kamera die Blende wählen.'],
 time:['Belichtungszeit','Längere Zeit sammelt mehr Licht und längere Bewegungsspuren. „Auto“ hält bei Blendenänderungen die Belichtung nach.'],
 iso:['ISO','ISO verstärkt das Signal, sammelt selbst kein Licht. Für einen fairen Rauschvergleich zugleich kürzer belichten. Auto-ISO gleicht die Helligkeit nach.'],
 focus:['Fokus','AF folgt dem zuletzt gewählten Motiv. Auf ein Objekt im Bild klicken oder „Fokus hier“ im Raum nutzen. Eine freie Stelle im Raum setzt manuellen Fokus.'],
 ev:['Szenenhelligkeit','+1 EV bedeutet doppelt so viel verfügbares Licht. Manuell wird das Bild heller; eine aktive Automatik gleicht dagegen nach.'],
 temperature:['Lichtfarbe','Die Lichtquelle kann warm oder kühl sein. Weißabgleich unter „Bild & Sensor“ passt die Wiedergabe daran an.'],
 comp:['Belichtungskorrektur','Verschiebt das Helligkeitsziel einer aktiven Automatik. In M ohne Auto-ISO bleibt die Korrektur wirkungslos.'],
 nd:['ND-Filter','Ein idealer Graufilter schwächt das Licht: 3 EV = ein Achtel. Eine aktive Automatik kann Zeit, Blende oder ISO nachführen.'],
 wb:['Weißabgleich','Gleiche Kelvin-Werte für Licht und Weißabgleich ergeben hier neutrale Farben. Auto-WB folgt der eingestellten Lichtfarbe.'],
 mp:['Sensorauflösung','Ändert Pixelabstand, Beugung relativ zum Pixel und das strenge Schärfekriterium. Die Vorschau erhält dadurch nicht mehr Bildpixel.'],
 body:['Kamerabauart','Bei einer DSLR ist der Spiegel während der Aufnahme hochgeklappt. Deshalb ändert die Bauart hier den Aufbau, nicht die Belichtung.'],
 sensor:['Sensorformat','Die Ausschnittssperre passt die reale Brennweite an. Ohne Sperre schneidet ein kleinerer Sensor einen engeren Bildwinkel aus.'],
 tripod:['Stativ & Stabilisierung','Beides reduziert Kamerabewegung, nicht Motivbewegung. Sichtbar vor allem bei längerer Belichtungszeit.']
};
const definitions=[
 {key:'focal',label:'Brennweite',list:focalStops,format:v=>`${Number(v.toFixed(1))} mm`},
 {key:'aperture',label:'Blende',list:apertures,format:v=>`ƒ/${Number(v.toFixed(1))}`,color:'light'},
 {key:'time',label:'Belichtungszeit',list:shutters,format:shutterText,color:'light'},
 {key:'iso',label:'ISO',list:isos,format:v=>`${Math.round(v)}`,color:'light'},
 {key:'focus',label:'Fokusdistanz',min:.3,max:50,step:.1,format:distanceText},
 {key:'comp',label:'Belichtungskorrektur',min:-3,max:3,step:.3,format:v=>`${v>0?'+':''}${v.toFixed(1)} EV`,area:'image'},
 {key:'nd',label:'ND-Filter',min:0,max:10,step:1,format:v=>`${v} EV`,area:'image',color:'light'},
 {key:'wb',label:'Weißabgleich',min:2500,max:10000,step:100,format:v=>`${Math.round(v)} K`,area:'image'},
 {key:'mp',label:'Sensorauflösung',min:8,max:100,step:1,format:v=>`${Math.round(v)} MP`,area:'image'},
 {key:'ev',label:'Szenenhelligkeit',min:3,max:16,step:.1,format:v=>`${v.toFixed(1)} EV₁₀₀`,area:'scene',color:'light'},
 {key:'temperature',label:'Lichtfarbe',min:2500,max:10000,step:100,format:v=>`${v} K`,area:'scene',color:'light'}
];
function controlHTML(d){const auto=['aperture','time','iso','focus','wb'].includes(d.key),marks=d.key==='focal'?`<div class="focal-marks">${[24,35,50,85,135].map(v=>`<button data-focal="${v}" style="left:${focalStops.indexOf(v)/(focalStops.length-1)*100}%" title="${v} mm einstellen">${v}</button>`).join('')}</div>`:'';return `<div class="control" data-color="${d.color||'focus'}"><div class="control-head"><label for="${d.key}">${d.label}</label><div class="control-value">${auto?`<button type="button" class="auto-pill" data-auto="${d.key}" aria-label="${d.key==='focus'?'Autofokus':d.key==='wb'?'Automatischen Weißabgleich':`Automatik für ${d.label}`} umschalten">${d.key==='focus'?'AF':'Auto'}</button>`:''}<output id="out-${d.key}" for="${d.key}"></output></div></div><input type="range" id="${d.key}" min="${d.list?0:d.min}" max="${d.list?d.list.length-1:d.max}" step="${d.list?1:d.step}" aria-describedby="help-${d.key}"><span class="sr-only" id="help-${d.key}">${help[d.key]?.[1]||''}</span>${marks}</div>`;}
$('main-controls').innerHTML=definitions.filter(d=>!d.area).map(controlHTML).join('');$('advanced-controls').innerHTML=definitions.filter(d=>d.area==='image').map(controlHTML).join('');$('scene-controls').innerHTML=definitions.filter(d=>d.area==='scene').map(controlHTML).join('');
$('sensor').innerHTML=Object.entries(sensors).map(([id,s])=>`<option value="${id}">${s.name} · ${s.w} × ${s.h} mm</option>`).join('');
$('room-actor').innerHTML=Object.entries(actors).map(([id,a])=>`<option value="${id}">${a.name}</option>`).join('');
$('page-learn').innerHTML=learnPage();$('page-atlas').innerHTML=atlasPage();$('page-about').innerHTML=aboutPage();
function settings(tab){settingsTab=tab;$('main-controls').hidden=tab!=='base';$('image-settings').hidden=tab!=='image';document.querySelectorAll('[data-settings]').forEach(b=>b.classList.toggle('active',b.dataset.settings===tab));needsRender=true;}
function explain(key){if(['focal','aperture','time','iso','focus'].includes(key))activeControl=key;if(help[key])$('control-explainer').innerHTML=`<b>${help[key][0]}</b><p>${help[key][1]}</p>`;document.querySelectorAll('#main-controls .control').forEach(el=>el.classList.toggle('is-active',el.querySelector('input').id===activeControl));document.querySelectorAll('[data-control]').forEach(b=>b.classList.toggle('active',b.dataset.control===activeControl));needsRender=true;}
function selectControl(key){settings('base');explain(key);$(key).focus({preventScroll:true});update();}
document.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>{settings(b.dataset.settings);explain(b.dataset.settings==='image'?'wb':activeControl);});document.querySelectorAll('[data-control]').forEach(b=>b.onclick=()=>selectControl(b.dataset.control));
definitions.forEach(d=>{$(d.key).addEventListener('input',()=>{state[d.key]=d.list?d.list[Number($(d.key).value)]:Number($(d.key).value);explain(d.key);update();});$(d.key).addEventListener('focus',()=>explain(d.key));});
function adopt(){const e=effective(state);Object.assign(state,{aperture:e.aperture,time:e.time,iso:e.iso,focus:e.focus,wb:e.wb});}
document.querySelectorAll('[data-auto]').forEach(b=>b.onclick=()=>{const key=b.dataset.auto,old=state.mode;adopt();if(key==='focus')state.autoFocus=!state.autoFocus;else if(key==='wb')state.autoWB=!state.autoWB;else if(key==='iso'){state.autoISO=old==='P'?false:!state.autoISO;if(old==='P')state.mode='M';}else if(key==='time')state.mode=old==='P'?'S':old==='A'?'M':'A';else if(key==='aperture')state.mode=old==='P'?'A':old==='S'?'M':'S';explain(key);update();});
$('mode').onchange=()=>{const next=$('mode').value;adopt();state.mode=next;explain(next==='S'?'aperture':next==='A'?'time':'iso');update();};
$('body').onchange=()=>{state.body=$('body').value;explain('body');update();};$('cocMode').onchange=()=>{state.cocMode=$('cocMode').value;explain('mp');update();};
for(const key of['matchFrame','tripod','stabilization','portrait','grid','zebra','peaking','motion'])$(key).onchange=()=>{state[key]=$(key).checked;if(['tripod','stabilization'].includes(key))explain('tripod');update();};
$('sensor').onchange=()=>{state=changeSensor(state,$('sensor').value);if(state.sensor==='phone'&&state.mode==='S')state.mode='M';explain('sensor');update();};
$('scene').onchange=()=>{state.scene=$('scene').value;Object.assign(state,{courtyard:{ev:11,temperature:5500},night:{ev:5,temperature:3800},studio:{ev:9,temperature:3200}}[state.scene]);update();};
document.querySelectorAll('[data-focal]').forEach(b=>b.onclick=()=>{state.focal=Number(b.dataset.focal);explain('focal');update();});
document.querySelectorAll('[data-ray]').forEach(b=>b.onchange=()=>{let points=[...document.querySelectorAll('[data-ray]:checked')].map(x=>x.dataset.ray);if(!points.length){b.checked=true;points=[b.dataset.ray];}state.rayTargets=points.join(',');update();});
const motionLabels={speed:'Person · Gehen',waveSpeed:'Hand · Winken',ballSpeed:'Balltempo',birdSpeed:'Flugtempo'};
document.querySelectorAll('[data-motion]').forEach(b=>b.onclick=()=>{motionTarget=b.dataset.motion;update();});$('motion-speed').oninput=()=>{state[motionTarget]=Number($('motion-speed').value);update();};
function focusActor(id){if(id==='camera')return;state.focus=actorDistance(state,id);state.afTarget=id;explain('focus');update();}
$('room-actor').onchange=()=>{roomSelected=$('room-actor').value;update();};
$('room-distance').oninput=()=>{const a=actors[roomSelected],value=Number($('room-distance').value);if(!$('room-distance').value.trim()||!Number.isFinite(value))return;state=moveActor(state,roomSelected,roomSelected==='camera'?-value:value-state.cameraBack);update();};
$('room-side').oninput=()=>{const a=actors[roomSelected],value=Number($('room-side').value);if(!$('room-side').value.trim()||!Number.isFinite(value))return;state=moveActor(state,roomSelected,roomSelected==='camera'?-state.cameraBack:state[a.z],value);update();};
for(const id of['room-distance','room-side'])$(id).onblur=()=>update();
$('room-focus').onclick=()=>focusActor(roomSelected);$('focus-subject').onclick=()=>focusActor('person');
$('auto-setup').onclick=()=>{state.mode='P';state.autoISO=true;state.autoFocus=true;state.afTarget='person';state.autoWB=true;state.comp=0;explain('iso');update();toast('Belichtung, Personenfokus und Weißabgleich werden automatisch nachgeführt.');};
function page(name){if(name==='lab'){$('library-dialog').close();return;}for(const p of $('library-dialog').querySelectorAll('.page'))p.hidden=p.id!==`page-${name}`;if(!$('library-dialog').open)$('library-dialog').showModal();$('library-dialog').scrollTop=0;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)page(b.dataset.page);if(b.dataset.experiment)openLesson(b.dataset.experiment);if(b.dataset.camera){state=changeSensor(state,b.dataset.camera);if(state.sensor==='phone'&&state.mode==='S')state.mode='M';page('lab');explain('sensor');update();}});
document.querySelector('.brand').onclick=e=>{e.preventDefault();page('lab');};
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
$('sensors-open').onclick=()=>{$('sensor-dialog').showModal();drawSensors($('sensor-canvas'),state);};
function update(){
 const m=metrics(state),s=m.s;needsRender=true;for(const key of['sensor','body','mode','cocMode','scene'])$(key).value=state[key];$('body').disabled=s.sensor==='phone';$('mode').querySelector('[value=S]').disabled=s.sensor==='phone';
 const automatic={aperture:s.mode==='S'||s.mode==='P'||s.sensor==='phone',time:s.mode==='A'||s.mode==='P',iso:s.autoISO||s.mode==='P',focus:s.autoFocus,wb:s.autoWB};
 for(const d of definitions){const value=s[d.key],el=$(d.key);el.value=d.list?d.list.indexOf(nearest(d.list,value)):value;$(`out-${d.key}`).textContent=d.format(value);el.setAttribute('aria-valuetext',d.format(value));el.disabled=Boolean(automatic[d.key])||(d.key==='comp'&&s.mode==='M'&&!s.autoISO);}
 document.querySelectorAll('[data-auto]').forEach(b=>{const key=b.dataset.auto;b.classList.toggle('active',Boolean(automatic[key]));b.setAttribute('aria-pressed',String(Boolean(automatic[key])));b.disabled=key==='aperture'&&s.sensor==='phone';b.textContent=b.disabled?'fest':key==='focus'?'AF':'Auto';});
 for(const key of['matchFrame','tripod','stabilization','portrait','grid','zebra','peaking','motion'])$(key).checked=state[key];$('portrait').disabled=s.sensor!=='phone';
 document.querySelectorAll('[data-focal]').forEach(b=>b.classList.toggle('selected',Math.abs(Number(b.dataset.focal)-s.focal)<.3));document.querySelectorAll('[data-ray]').forEach(b=>b.checked=s.rayTargets.split(',').includes(b.dataset.ray));document.querySelectorAll('[data-motion]').forEach(b=>b.classList.toggle('active',b.dataset.motion===motionTarget));
 $('motion-label').textContent=motionLabels[motionTarget];$('motion-speed').value=state[motionTarget];$('out-motion-speed').textContent=`${state[motionTarget].toFixed(1)} m/s`;
 const a=actors[roomSelected];$('room-actor').value=roomSelected;$('room-distance-label').textContent=roomSelected==='camera'?'Rückzug · m':'Entfernung · m';$('room-distance').min=roomSelected==='camera'?0:a.min+s.cameraBack;$('room-distance').max=roomSelected==='camera'?8:a.max+s.cameraBack;if(document.activeElement!==$('room-distance'))$('room-distance').value=actorDistance(s,roomSelected).toFixed(1);$('room-side').disabled=!a.x;if(document.activeElement!==$('room-side'))$('room-side').value=a.x?s[a.x].toFixed(1):'';$('room-focus').disabled=roomSelected==='camera';
 $('room-summary').innerHTML=`<span>${s.autoFocus?'AF · '+actors[s.afTarget].name:'Manueller Fokus'} <strong>${distanceText(s.focus)}</strong></span><span>Ziehen: Position · Feld: exakter Wert</span>`;
 $('photo-settings').innerHTML=`<span>${s.mode}</span><span>ƒ/${Number(s.aperture.toFixed(1))}</span><span>${shutterText(s.time)}</span><span>ISO ${Math.round(s.iso)}</span><span>${Number(s.focal.toFixed(1))} mm</span>`;
 $('photo-help').textContent=s.zebra?'Zebra-Warnung: Rot schraffiert = abgeschnittene Lichter.':s.motion?'Bewegung läuft. Abspielen ausschalten = Bild anhalten.':'Bild anklicken: fokussieren. Abspielen startet die bewegte Vorschau.';
 $('metrics').innerHTML=`<div class="metric ${Math.abs(m.offset)>1?'warn':''}"><div class="label">BELICHTUNG</div><div class="value">${m.offset>=0?'+':''}${m.offset.toFixed(1)} EV</div><div class="sub">zur Szenenreferenz</div></div><div class="metric teal"><div class="label">SCHARF ERSCHEINEND</div><div class="value">${distanceText(m.near)} – ${distanceText(m.far)}</div><div class="sub">c = ${(m.coc*1000).toFixed(1)} µm</div></div><div class="metric"><div class="label">BILDWINKEL · HORIZONTAL</div><div class="value">${m.fov.toFixed(1)}°</div><div class="sub">${m.equivalent.toFixed(0)} mm KB-äquivalent</div></div><div class="metric"><div class="label">LICHT PRO SENSORFLÄCHE</div><div class="value">${m.physical.toFixed(m.physical<.1?3:2)}×</div><div class="sub">Signalverstärkung ${(s.iso/100).toFixed(1)}×</div></div>`;
 const captions={focal:'Die Linsengruppen bestimmen den Bildwinkel. Die Motivpunkte zeigen Lichtwege aus verschiedenen Entfernungen.',aperture:'Die mechanische Blende begrenzt den Strahlenkegel. Gestrichelte Kreise in der Lupe zeigen das Schärfekriterium.',focus:`${s.autoFocus?'AF folgt '+actors[s.afTarget].name:'Manueller Fokus'}: ${distanceText(s.focus)}. Nur die passende Objektebene wird auf dem Sensor scharf abgebildet.`,time:`Der Verschluss lässt Licht für ${shutterText(s.time)} durch. Die Zeit ändert die Dauer, nicht die Blendenöffnung.`,iso:`ISO ${Math.round(s.iso)} verstärkt nach dem Sensor. Die Lichtwege bleiben gleich; weniger gesammeltes Licht macht Körnung deutlicher.`};
 $('camera-caption').textContent=captions[activeControl];
 $('insight').innerHTML=Math.abs(m.offset-s.comp)>.3&&(s.mode!=='M'||s.autoISO)?'<span class="warning">Automatikgrenze erreicht: Licht, ND oder Vorgaben anpassen.</span>':Math.abs(m.offset)>1.5?'<span class="warning">Belichtung weit vom Referenzwert. „Auto einrichten“ hilft beim Neueinstieg.</span>':'Tempo 0 = still. Zeit und Tempo bestimmen die Spur; Abspielen steuert nur den Ablauf.';
 $('lesson-current').hidden=!activeLesson;if(activeLesson){$('lesson-current').textContent=`Versuch ${activeLesson.n}${activeLesson.check(s)?' ✓':''}`;$('lesson-current').title=activeLesson.goal;}
}
function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
$('reset').onclick=()=>{state={...defaults};simTime=0;motionTarget='ballSpeed';roomSelected='person';activeLesson=null;settings('base');history.replaceState(null,'',location.href.split('#')[0]);explain('aperture');update();toast('Ausgangseinstellungen wiederhergestellt.');};
$('share').onclick=async()=>{const url=location.href.split('#')[0]+'#s='+encodeState(state);history.replaceState(null,'',url);try{await navigator.clipboard.writeText(url);toast('Link mit deinen Einstellungen kopiert.');}catch{$('lesson-content').innerHTML='<h2>Versuch teilen</h2><p>Der Link enthält Kamera und Szene.</p><textarea id="share-url" rows="5" style="width:100%"></textarea>';$('share-url').value=url;$('lesson-dialog').showModal();$('share-url').select();}};
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#s=')){state=decodeState(location.hash);update();}});
$('snapshot').onclick=()=>{saved=structuredClone(state);$('compare').disabled=false;$('snapshot').textContent='A aktualisieren';toast('A gespeichert. Jetzt einen Regler ändern und A/B vergleichen.');};
function shortSettings(raw){const {s,sensor}=metrics(raw);return `${sensor.name} · ${Number(s.focal.toFixed(1))} mm · ƒ/${Number(s.aperture.toFixed(1))} · ${shutterText(s.time)} · ISO ${Math.round(s.iso)}`;}
$('compare').onclick=()=>{if(!saved)return;drawPhoto($('compare-a'),saved,0,{clean:true});drawPhoto($('compare-b'),state,0,{clean:true});$('compare-a-caption').innerHTML='<strong>A · Gespeichert</strong><br>'+shortSettings(saved);$('compare-b-caption').innerHTML='<strong>B · Aktuell</strong><br>'+shortSettings(state);const rows=comparisonRows(saved,state);$('compare-diff').innerHTML=rows.length?`<h3>Diese Werte unterscheiden sich</h3><table><thead><tr><th>Parameter</th><th>A · Gespeichert</th><th>B · Aktuell</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${r.key}</th><td>${r.a}</td><td class="changed">${r.b}</td></tr>`).join('')}</tbody></table>`:'<p>Die Einstellungen sind noch gleich. Schließe den Vergleich und ändere einen Regler.</p>';$('compare-dialog').showModal();};
$('download').onclick=()=>{render(simTime);canvas.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fotolabor-aufnahme.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Aufnahmebild als PNG exportiert.');});};
function openLesson(id){const l=lessons.find(x=>x.id===id);if(!l)return;$('lesson-content').innerHTML=`<p class="eyebrow">EXPERIMENT ${l.n} · ${l.topic}</p><h2>${l.title}</h2><p>${l.intro}</p><ol>${l.steps.map(x=>`<li>${x}</li>`).join('')}</ol><div class="lesson-check"><strong>Denkfrage</strong><br>${l.question}</div><details><summary>Erklärung anzeigen</summary><p class="reveal">${l.answer}</p></details><p class="micro">Ziel: ${l.goal}</p><button id="start-lesson" class="primary">Mit Ausgangseinstellungen starten ↗</button><button id="stop-lesson" class="quiet">Versuch beenden</button>`;$('start-lesson').onclick=()=>{state={...defaults,...l.setup};simTime=0;activeLesson=l;motionTarget=l.id==='motion'?'speed':'ballSpeed';page('lab');settings('base');$('lesson-dialog').close();explain(l.id==='iso'?'iso':'aperture');update();};$('stop-lesson').onclick=()=>{activeLesson=null;$('lesson-dialog').close();update();};if(!$('lesson-dialog').open)$('lesson-dialog').showModal();}
$('lesson-current').onclick=()=>activeLesson&&openLesson(activeLesson.id);
function resize(){for(const cv of[canvas,cameraCanvas,spaceCanvas]){const r=cv.getBoundingClientRect();if(!r.width||!r.height)continue;const d=Math.min(devicePixelRatio||1,1.5),w=Math.round(r.width*d),h=Math.round(r.height*d);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;needsRender=true;}}}
for(const cv of[canvas,cameraCanvas,spaceCanvas])new ResizeObserver(resize).observe(cv);
function point(cv,e){const r=cv.getBoundingClientRect();return{x:(e.clientX-r.left)*cv.width/r.width,y:(e.clientY-r.top)*cv.height/r.height};}
canvas.addEventListener('pointerdown',e=>{if(!photoHit)return;const p=point(canvas,e),hits=photoHit.boxes.filter(b=>p.x>=b.x&&p.x<=b.x+b.w&&p.y>=b.y&&p.y<=b.y+b.h);if(hits.length){const hit=hits.sort((a,b)=>a.z-b.z)[0],id={person:'person',hand:'person',plant:'plant',bird:'bird',wings:'bird',ball:'ball',sculpture:'sculpture'}[hit.id]||'background';focusActor(id);}});
spaceCanvas.addEventListener('pointerdown',e=>{if(!spaceHit)return;const p=point(spaceCanvas,e),hit=spaceHit.hits.find(h=>Math.hypot(h.x-p.x,h.y-p.y)<25);if(hit){roomSelected=hit.id;const a=actors[hit.id];drag={id:hit.id,start:p,z:hit.id==='camera'?-state.cameraBack:state[a.z],x:a.x?state[a.x]:0,scale:spaceHit.scale,bounds:{minZ:spaceHit.minZ,maxZ:spaceHit.maxZ}};spaceCanvas.setPointerCapture(e.pointerId);update();}else{state.focus=clamp((p.x-spaceHit.margin)/spaceHit.scale+spaceHit.minZ+state.cameraBack,.3,50);state.autoFocus=false;explain('focus');update();}});
spaceCanvas.addEventListener('pointermove',e=>{const p=point(spaceCanvas,e);if(!drag){spaceCanvas.style.cursor=spaceHit?.hits.some(h=>Math.hypot(h.x-p.x,h.y-p.y)<25)?'grab':'crosshair';return;}state=moveActor(state,drag.id,drag.z+(p.x-drag.start.x)/drag.scale,drag.x-(p.y-drag.start.y)/drag.scale);update();});
for(const event of['pointerup','pointercancel'])spaceCanvas.addEventListener(event,()=>{drag=null;needsRender=true;});
cameraCanvas.addEventListener('pointerdown',e=>{if(!cameraHit)return;const p=point(cameraCanvas,e),hit=cameraHit.parts.find(h=>Math.abs(p.x-h.x)<h.w/2&&Math.abs(p.y-h.y)<h.h/2);if(hit)selectControl(hit.key);});
cameraCanvas.addEventListener('pointermove',e=>{const p=point(cameraCanvas,e);cameraCanvas.style.cursor=cameraHit?.parts.some(h=>Math.abs(p.x-h.x)<h.w/2&&Math.abs(p.y-h.y)<h.h/2)?'pointer':'default';});
function render(t,onlyPhoto=false){photoHit=drawPhoto(canvas,state,t);if(!onlyPhoto){cameraHit=drawCutaway(cameraCanvas,state,{active:activeControl});spaceHit=drawRoom(spaceCanvas,state,{selected:roomSelected,bounds:drag?.bounds});}}
function animate(now){const dt=Math.min((now-lastTick)/1000,.1);lastTick=now;const moving=state.motion&&!document.hidden;if(moving)simTime+=dt;if(needsRender||(moving&&now-lastTime>80)){render(simTime,!needsRender);needsRender=false;lastTime=now;}requestAnimationFrame(animate);}
explain('aperture');update();resize();requestAnimationFrame(animate);
